INSERT INTO volunteer (id, volunteer_department, level)
SELECT #{id}, department_id, #{level}
FROM department
WHERE department_id = #{departmentId}
   OR department_name = #{departmentId}
    LIMIT 1
ON DUPLICATE KEY UPDATE
                     volunteer_department = VALUES(volunteer_department),
                     level = VALUES(level)

